window.XV_TIMING = {"total":81251,"scenes":[{"start":0,"dur":17393},{"start":17393,"dur":7733},{"start":25126,"dur":14870},{"start":39996,"dur":22127},{"start":62123,"dur":11536},{"start":73659,"dur":7592}],"cues":{"v1a":650,"v1b":4686,"v1c":8110,"v1d":13146,"v2a":18043,"v2b":22067,"v3a":25776,"v3b":27242,"v3c":30373,"v3d":34546,"v4a":40646,"v4b":43296,"v4c":48527,"v4d":51828,"v4e":54058,"v4f":56309,"v4g":58134,"v5a":62773,"v5b":67550,"v5c":68375,"v5d":69273,"v5e":70435,"v5f":71347,"v6a":74309,"v6b":77969},"captions":{"en":[{"id":"v1a","scene":0,"start":650,"end":4636,"text":"Ten years ago, sustainability reporting was a nice extra."},{"id":"v1b","scene":0,"start":4686,"end":7064,"text":"Today, it’s becoming unavoidable."},{"id":"v1c","scene":0,"start":8110,"end":13096,"text":"In 2025, over 22,000 companies reported to CDP."},{"id":"v1d","scene":0,"start":13146,"end":16743,"text":"Together, they’re worth more than half the world’s stock market."},{"id":"v2a","scene":1,"start":18043,"end":21384,"text":"Yes, it’s about protecting the planet and its people."},{"id":"v2b","scene":1,"start":22067,"end":24476,"text":"But there’s a reason much closer to home."},{"id":"v3a","scene":2,"start":25776,"end":26992,"text":"Your customers."},{"id":"v3b","scene":2,"start":27242,"end":30233,"text":"Whether you sell to businesses, or to consumers,"},{"id":"v3c","scene":2,"start":30373,"end":33396,"text":"they’re comparing you with a more sustainable competitor."},{"id":"v3d","scene":2,"start":34546,"end":39346,"text":"EcoVadis already rates more than 175,000 companies."},{"id":"v4a","scene":3,"start":40646,"end":42746,"text":"And then, Europe made it law."},{"id":"v4b","scene":3,"start":43296,"end":47880,"text":"Under the CSRD, the largest companies must now report in detail."},{"id":"v4c","scene":3,"start":48527,"end":51437,"text":"To do that, they need data from their suppliers."},{"id":"v4d","scene":3,"start":51828,"end":53150,"text":"And that means you."},{"id":"v4e","scene":3,"start":54058,"end":56209,"text":"But being transparent isn’t enough."},{"id":"v4f","scene":3,"start":56309,"end":58129,"text":"You have to show you’re improving,"},{"id":"v4g","scene":3,"start":58134,"end":60776,"text":"on environment, social and governance."},{"id":"v5a","scene":4,"start":62773,"end":66576,"text":"The good news? Start early, and it’s easier than it looks."},{"id":"v5b","scene":4,"start":67550,"end":68268,"text":"Measure."},{"id":"v5c","scene":4,"start":68375,"end":69243,"text":"Decide."},{"id":"v5d","scene":4,"start":69273,"end":70405,"text":"Disclose."},{"id":"v5e","scene":4,"start":70435,"end":71095,"text":"Act."},{"id":"v5f","scene":4,"start":71347,"end":72909,"text":"One step at a time."},{"id":"v6a","scene":5,"start":74309,"end":77755,"text":"Ready to start? Explore the free resources below."},{"id":"v6b","scene":5,"start":77969,"end":79395,"text":"Or write to me today."}],"fr":[{"id":"v1a","scene":0,"start":650,"end":4522,"text":"Il y a dix ans, le reporting de durabilité était un petit plus."},{"id":"v1b","scene":0,"start":4686,"end":7160,"text":"Aujourd’hui, il devient incontournable."},{"id":"v1c","scene":0,"start":8110,"end":12497,"text":"En 2025, plus de 22 000 entreprises ont répondu au CDP."},{"id":"v1d","scene":0,"start":13146,"end":16590,"text":"Ensemble, elles pèsent plus de la moitié de la bourse mondiale."},{"id":"v2a","scene":1,"start":18043,"end":21917,"text":"Bien sûr, il s’agit de protéger la planète et ceux qui y vivent."},{"id":"v2b","scene":1,"start":22067,"end":24469,"text":"Mais il y a une raison bien plus proche de vous."},{"id":"v3a","scene":2,"start":25776,"end":26674,"text":"Vos clients."},{"id":"v3b","scene":2,"start":27242,"end":30423,"text":"Que vous vendiez à des entreprises, ou à des particuliers,"},{"id":"v3c","scene":2,"start":30373,"end":32758,"text":"ils vous comparent à un concurrent plus durable."},{"id":"v3d","scene":2,"start":34546,"end":38130,"text":"EcoVadis note déjà plus de 175 000 entreprises."},{"id":"v4a","scene":3,"start":40646,"end":42258,"text":"Puis l’Europe en a fait une loi."},{"id":"v4b","scene":3,"start":43296,"end":48177,"text":"Avec la CSRD, les plus grandes entreprises doivent désormais tout publier en détail."},{"id":"v4c","scene":3,"start":48527,"end":51778,"text":"Pour cela, elles ont besoin des données de leurs fournisseurs."},{"id":"v4d","scene":3,"start":51828,"end":53308,"text":"C’est-à-dire, vous."},{"id":"v4e","scene":3,"start":54058,"end":56064,"text":"Mais la transparence ne suffit pas."},{"id":"v4f","scene":3,"start":56309,"end":58234,"text":"Il faut montrer que vous progressez,"},{"id":"v4g","scene":3,"start":58134,"end":61173,"text":"sur l’environnement, le social et la gouvernance."},{"id":"v5a","scene":4,"start":62773,"end":66800,"text":"La bonne nouvelle ? En commençant tôt, c’est plus simple qu’il n’y paraît."},{"id":"v5b","scene":4,"start":67550,"end":68345,"text":"Mesurer."},{"id":"v5c","scene":4,"start":68375,"end":69220,"text":"Décider."},{"id":"v5d","scene":4,"start":69273,"end":70055,"text":"Publier."},{"id":"v5e","scene":4,"start":70435,"end":71247,"text":"Agir."},{"id":"v5f","scene":4,"start":71347,"end":72525,"text":"Une étape à la fois."},{"id":"v6a","scene":5,"start":74309,"end":77769,"text":"Prêt à commencer ? Explorez les ressources gratuites ci-dessous."},{"id":"v6b","scene":5,"start":77969,"end":79701,"text":"Ou écrivez-moi dès aujourd’hui."}]},"audio":{"en":"assets/audio/explainer-en.m4a?v=7db3ebab","fr":"assets/audio/explainer-fr.m4a?v=3f389a49"},"voices":{"en":"Daniel","fr":"Thomas"}};
